use std::{fs,path::Path,collections::{BTreeSet,BTreeMap}};use serde_json::{Value,json};use sha2::{Sha256,Digest};
const ROOT:&str="/home/ubuntu/src/zopro-perf-work/store-frame221";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn med(mut a:[f64;3])->f64{a.sort_by(f64::total_cmp);a[1]}
fn close(a:f64,b:f64){assert!((a-b).abs()<=1e-10*a.abs().max(b.abs()).max(1.));}
fn main(){let root=Path::new(ROOT);let result=read(root.join("result.json"));let jobs=read(root.join("jobs.json"));let mut rows=BTreeMap::new();let mut stages=BTreeMap::new();let mut ledger:BTreeSet<String>=serde_json::from_value(read("/home/ubuntu/src/zopro-perf-work/page-frame220/proof-sha256-after-main.json")).unwrap();let mut receipts=0;let mut records=0;for j in jobs.as_array().unwrap(){let name=j["name"].as_str().unwrap();let smoke=j["smoke"]==true;let d=root.join(format!("{}-run/{name}",if smoke{"smoke"}else{"main"}));let vd=root.join(format!("{}-run/verify-{name}",if smoke{"smoke"}else{"verify"}));for p in[&d,&vd]{let receipt=read(p.join("exit.json"));assert_eq!(receipt["returncode"],0);for s in["stdout","stderr"]{assert_eq!(hash(p.join(format!("{s}.log"))),receipt[format!("{s}_sha256")]);}receipts+=1;}let out=fs::read_to_string(d.join("stdout.log")).unwrap();let mut samples=vec![];let mut summary=None;for line in out.lines(){if let Some(s)=line.strip_prefix("SAMPLE "){let v:Value=serde_json::from_str(s).unwrap();assert_eq!(v["round"],samples.len());samples.push(v["ms"].as_f64().unwrap());}if let Some(s)=line.strip_prefix("SUMMARY "){assert!(summary.is_none());summary=Some(serde_json::from_str::<Value>(s).unwrap());}}let n=j["rounds"].as_u64().unwrap()as usize;assert_eq!(samples.len(),n);records+=n;let summary=summary.unwrap();let mean=samples.iter().fold(0.,|sum,x|sum+x)/n as f64;let cpu=(summary["user_cpu_ms"].as_f64().unwrap()+summary["system_cpu_ms"].as_f64().unwrap())/n as f64;let rss=summary["whole_process_maxrss_kib"].as_f64().unwrap()/1024.;let recorded=result["rows"].as_array().unwrap().iter().find(|r|r["job"]["name"]==name).unwrap();close(mean,recorded["mean_ms"].as_f64().unwrap());close(cpu,recorded["cpu_ms"].as_f64().unwrap());close(rss,recorded["peak_rss_mib"].as_f64().unwrap());let mut cycles=vec![];let mut instructions=vec![];for p in out.lines().filter_map(|l|l.strip_prefix("PHASE ")){let p:Value=serde_json::from_str(p).unwrap();cycles.push(p["group_pmu"][1].as_u64().unwrap()-p["group_pmu"][0].as_u64().unwrap());instructions.push(p["group_pmu"][3].as_u64().unwrap()-p["group_pmu"][2].as_u64().unwrap());}cycles.sort_unstable();instructions.sort_unstable();assert_eq!(cycles.len(),n);let pair=(cycles[n/2],instructions[n/2]);close(pair.0 as f64,recorded["medians"]["group_cycles"].as_f64().unwrap());close(pair.1 as f64,recorded["medians"]["group_instructions"].as_f64().unwrap());if !smoke{stages.insert((j["context"].as_str().unwrap().to_string(),j["mode"].as_str().unwrap().to_string(),j["block"].as_u64().unwrap()as usize),pair);rows.insert((j["context"].as_str().unwrap().to_string(),j["mode"].as_str().unwrap().to_string(),j["block"].as_u64().unwrap()as usize),(mean,cpu,rss));}let proofdir=Path::new(j["proof_dir"].as_str().unwrap());let proof=hash(proofdir.join("0.proof"));assert!(ledger.insert(proof.clone()));assert_eq!(hash(proofdir.join("0.public")),j["public_sha256"]);let verifier=fs::read_to_string(vd.join("stdout.log")).unwrap();assert!(verifier.contains(&format!("VERIFIED proof_sha256={proof} ")));}
let value=|ctx:&str,m:&str,b:usize|rows[&(ctx.to_string(),m.to_string(),b)];let mut ready=true;let mut contrasts=vec![];for ctx in["1x2-w16","1x2-w32"]{for control in["REF","OFF"]{let ratios=std::array::from_fn::<_,3,_>(|b|value(ctx,"ON",b).0/value(ctx,control,b).0);let cpu=med(std::array::from_fn(|b|value(ctx,"ON",b).1/value(ctx,control,b).1));let peak=|m:&str|(0..3).map(|b|value(ctx,m,b).2).max_by(f64::total_cmp).unwrap();let wins=ratios.iter().filter(|&&x|x<1.).count();let latency=if ctx=="1x2-w32"{med(ratios)<1.&&wins>=2}else{med(ratios)<=1.02};let pass=latency&&cpu<=1.02&&peak("ON")<=1.10*peak(control)+8.;ready&=pass;let recorded=result["comparisons"].as_array().unwrap().iter().find(|v|v["control"]==control&&v["context"]==ctx).unwrap();close(med(ratios),recorded["paired_median"].as_f64().unwrap());close(cpu,recorded["cpu_ratio"].as_f64().unwrap());assert_eq!(recorded["pass"],pass);contrasts.push(json!({"context":ctx,"control":control,"ratios":ratios,"pass":pass}));}let calibration=med(std::array::from_fn(|b|value(ctx,"OFF",b).0/value(ctx,"REF",b).0));let pass=(1./1.03..=1.03).contains(&calibration);ready&=pass;let got=result["calibrations"].as_array().unwrap().iter().find(|v|v["context"]==ctx).unwrap();close(calibration,got["OFF_over_REF"].as_f64().unwrap());assert_eq!(got["pass"],pass);for b in 0..3{let get=|m:&str|stages[&(ctx.to_string(),m.to_string(),b)];let off=get("OFF");let on=get("ON");let got=result["stage_comparisons"].as_array().unwrap().iter().find(|v|v["context"]==ctx&&v["block"]==b).unwrap();close(on.0 as f64/off.0 as f64,got["ON_OFF_cycles"].as_f64().unwrap());close(on.1 as f64/off.1 as f64,got["ON_OFF_instructions"].as_f64().unwrap());}}assert_eq!(result["ready_for_qualification"],ready);
let mut changed=vec![];let mut exact=0;let old=read("/home/ubuntu/src/zopro-perf-work/group-profile216/source/.xtask/source-pins.json");for(p,h)in old.as_object().unwrap(){let rel=p.strip_prefix("/home/ubuntu/src/zopro-perf-work/group-profile216/source/").unwrap();if hash(root.join("source-v2").join(rel))==h.as_str().unwrap(){exact+=1;}else{changed.push(rel);}}assert_eq!(changed,["crates/zopro-core/src/msm_affine.rs","crates/zopro-core/src/msm_affine/grouping.rs"]);assert_eq!(exact,180);let before=fs::read_to_string("/home/ubuntu/src/zopro-perf-work/group-profile216/source/crates/zopro-core/src/msm_affine/grouping.rs").unwrap();let current=fs::read_to_string(root.join("source-v2/crates/zopro-core/src/msm_affine/grouping.rs")).unwrap();let block="\n    #[cfg(all(zopro_page_safe_group_frame,target_arch=\"x86_64\",target_feature=\"avx512ifma\",not(no_ifma)))]\n    let mut page_frame=PageAlignedFrame{_byte:0};\n    #[cfg(all(zopro_page_safe_group_frame,target_arch=\"x86_64\",target_feature=\"avx512ifma\",not(no_ifma)))]\n    std::hint::black_box(&mut page_frame);";let tail=format!("\n#[cfg(all(zopro_page_safe_group_frame,target_arch=\"x86_64\",target_feature=\"avx512ifma\",not(no_ifma)))]\n#[repr(align(32))]\nstruct PageAlignedFrame{{_byte:u8}}\n{}",fs::read_to_string(root.join("guard-tests.rs")).unwrap());assert_eq!(before,current.strip_suffix(&tail).unwrap().replace(block,""));let lib=fs::read_to_string(root.join("source-v2/crates/zopro-core/src/lib.rs")).unwrap();let lines=lib.lines().collect::<Vec<_>>();let at=lines.iter().position(|l|*l=="pub mod boolean_phase_trace;").unwrap();let attr=lines[at-1];let mut trace=fs::read_to_string(root.join("source-v2/crates/zopro-core/src/msm_affine.rs")).unwrap();for name in["group_begin","group_end"]{let original=format!("    crate::boolean_phase_trace::{name}();");let guarded=format!("    {attr}\n{original}");assert_eq!(trace.matches(&guarded).count(),1);trace=trace.replace(&guarded,&original);}assert_eq!(trace,fs::read_to_string("/home/ubuntu/src/zopro-perf-work/group-profile216/source/crates/zopro-core/src/msm_affine.rs").unwrap());assert_eq!(ledger.len(),59095);let stored:BTreeSet<String>=serde_json::from_value(read(root.join("proof-sha256-after-main.json"))).unwrap();assert_eq!(ledger,stored);assert_eq!(records,4521);assert_eq!(receipts,42);let out=json!({"pass":true,"ready_for_qualification":ready,"independent_contrasts":contrasts,"source216_exact":exact,"source216_changed":changed,"source216_default_construction_retained":true,"receipts":receipts,"stream_hashes":receipts*2,"records":records,"fresh_Gnark_exports":21,"canonical_count":ledger.len(),"canonical_sha256":hash(root.join("proof-sha256-after-main.json"))});let p=root.join("review.json");assert!(!p.exists());fs::write(p,serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("Independent reader PASS; qualificationready={ready};{receipts}receipts;ledger{}",ledger.len());}
